#!/usr/bin/env python3
"""
TROCA DE VENDA (superadmin) — "CONSULTAR HP" e "TRANSFERIR VENDA".

CONSULTAR HP  (botão ao lado do ID da transação, só para superadmin; NÃO altera nada)
  Procura o HP (transaction_id) em telao_events e abre um popup com: Nome do Lead, E-mail, Vertical, Produto, Valor e Cupom;
  a CONFERÊNCIA do que o closer digitou (nome, produto, vertical) contra o banco; e a linha traduzida em português:
  Self-Checkout · Venda de Embaixador · já é de OUTRO closer · co-closer · parcela de assinatura (e se já existe regra).
  Se o HP não existe, mostra IDs parecidos e vendas com o mesmo nome de lead (ajuda a achar o erro de digitação).

TRANSFERIR VENDA  (dentro do "Conceder", antes de escrever a resposta; já devolve o status num popup)
  Usa a MESMA lógica da rota pública /api/public/transfer-sale:
    • Self-Checkout            → CORRIGE: vira venda do closer que pediu.
    • Embaixador / sem closer  → DIVIDE: o closer entra como co-closer (a venda original fica intacta; o total da empresa não duplica).
    • Já é de OUTRO closer     → o popup pergunta: DIVIDIR (co-closer) ou TRANSFERIR TOTALMENTE (o closer que pediu vira o dono).
    • Parcela de assinatura    → também grava a regra para as parcelas FUTURAS; as anteriores só mudam se você clicar em "Aplicar às parcelas anteriores".
  Depois de gravar, RELÊ o banco e mostra o que foi confirmado. Clicar de novo não duplica ("nada a fazer"). Registra auditoria (quem, quando, antes e depois).

ANTES DE USAR: rode no Supabase o arquivo migration-transferencias.sql (cria só a tabela de auditoria; seguro rodar de novo). Sem ela a transferência funciona e o popup avisa.

Arquivos NOVOS (5): lib/vendas/hp.ts · lib/vendas/hp-handlers.ts · components/vendas/HpModais.tsx · app/api/admin/trocas/[id]/consultar-hp/route.ts · app/api/admin/trocas/[id]/transferir/route.ts
Arquivo ALTERADO (1): components/vendas/TrocaCard.tsx
SEGURANÇA: antes de gravar guarda uma cópia exata (<arquivo>.bak-hp); --desfazer restaura e remove os arquivos novos. Tudo-ou-nada: se um trecho não for reconhecido, o arquivo NÃO é tocado e o script diz qual.
Rodar de novo não duplica. Preserva CRLF/LF e BOM.

Uso (na RAIZ do projeto):   python aplicar-consultar-hp.py .   |  --dry-run (só mostra)  |  --desfazer
"""
import os, re, sys

NOVOS = {
  'lib/vendas/hp.ts': '// ══ Vendas — "Consultar HP" e "Transferir Venda" (superadmin): regras PURAS (sem banco, sem tela) ═══════════════════\n//  • Conferir o ID (HP) que o closer digitou contra a linha real de telao_events, em português.\n//  • Decidir COMO transferir (mesma lógica da rota pública /api/public/transfer-sale):\n//      - Self-Checkout            → CORRIGIR: vira venda do closer (closer_id exige a tabela closers)\n//      - Embaixador / sem closer  → DIVIDIR : o closer entra como co-closer (co_closer_id exige a tabela profiles); a venda original continua intacta (uma linha só, o total da empresa não duplica)\n//      - Já é de OUTRO closer     → o superadmin ESCOLHE: DIVIDIR (co-closer) ou TOTAL (o closer que pediu vira o dono e o outro deixa de ter o crédito)\n//    Se a venda é uma parcela de assinatura, grava também a regra para as parcelas FUTURAS (subscription_transfers).\nimport { fmtDataHora } from \'./format\'\n\nexport type Modo = \'corrigir\' | \'dividir\' | \'total\'\nexport type Origem = \'self_checkout\' | \'embaixador\' | \'closer\' | \'sem_origem\'\nexport type Situacao = \'ja_do_solicitante\' | \'self_checkout\' | \'embaixador\' | \'de_outro_closer\' | \'sem_closer\'\nexport type Tom = \'ok\' | \'atencao\' | \'info\' | \'erro\'\n\nexport interface VendaBanco {\n  id: string; transaction_id: string | null; lead_name: string | null; email: string | null; vertical: string | null; product: string | null; value: number | string | null; coupon_code: string | null; occurred_at: string | null\n  seller_type: string | null; is_self_checkout: boolean | null; sold_by_ambassador: boolean | null; ambassador_name: string | null\n  closer_id: string | null; closer_name: string | null; closer_hubspot_id: string | null; co_closer_id: string | null; co_closer_hubspot_id: string | null\n  transferred_at: string | null; transfer_reason: string | null; sale_type: string | null; is_recurring: boolean | null; installment_number: number | null; total_installments: number | null; subscription_id: string | null\n}\n/** O closer que pediu a troca, com os DOIS ids (closer_id aponta para closers; co_closer_id aponta para profiles). */\nexport interface Solicitante { profileId: string | null; closerId: string | null; hubspotId: string | null; nome: string }\nexport interface RegraAssinatura { mode: string | null; co_closer_id: string | null; co_closer_hubspot_id: string | null; reason?: string | null }\nexport interface Linha { chave: string; titulo: string; texto: string; tom: Tom }\n\nexport const normalizar = (s?: string | null) => (s ?? \'\').toLowerCase().normalize(\'NFD\').replace(/[\\u0300-\\u036f]/g, \'\').replace(/[^a-z0-9]+/g, \' \').trim()\nexport const escapeLike = (s: string) => s.replace(/[\\\\%_]/g, m => \'\\\\\' + m)\nconst hub = (s?: string | null) => (s == null ? \'\' : String(s).trim())\n\n/** Quem é o closer que pediu, nessa venda: principal (closer_id/closer_hubspot_id) e/ou co-closer. */\nexport function souEu(v: VendaBanco, s: Solicitante): { principal: boolean; co: boolean } {\n  const principal = (!!v.closer_id && !!s.closerId && v.closer_id === s.closerId) || (!!hub(v.closer_hubspot_id) && !!hub(s.hubspotId) && hub(v.closer_hubspot_id) === hub(s.hubspotId))\n  const co = (!!v.co_closer_id && !!s.profileId && v.co_closer_id === s.profileId) || (!!hub(v.co_closer_hubspot_id) && !!hub(s.hubspotId) && hub(v.co_closer_hubspot_id) === hub(s.hubspotId))\n  return { principal, co }\n}\nexport function origemDe(v: VendaBanco): Origem {\n  if (v.is_self_checkout === true || v.seller_type === \'self_checkout\') return \'self_checkout\'\n  if (v.seller_type === \'ambassador\' || v.sold_by_ambassador === true) return \'embaixador\'\n  if (v.seller_type === \'closer\') return \'closer\'\n  return \'sem_origem\'\n}\nexport function situacaoDe(v: VendaBanco, s: Solicitante): Situacao {\n  const eu = souEu(v, s)\n  if (eu.principal || eu.co) return \'ja_do_solicitante\'\n  if (origemDe(v) === \'self_checkout\') return \'self_checkout\'\n  if (v.closer_id || hub(v.closer_hubspot_id)) return \'de_outro_closer\'\n  return origemDe(v) === \'embaixador\' ? \'embaixador\' : \'sem_closer\'\n}\n/** O modo que o sistema usa sozinho; null = precisa o superadmin escolher. */\nexport const modoPadrao = (sit: Situacao): Modo | null => (sit === \'self_checkout\' ? \'corrigir\' : sit === \'embaixador\' || sit === \'sem_closer\' ? \'dividir\' : null)\nexport const modosPermitidos = (sit: Situacao): Modo[] => (sit === \'self_checkout\' ? [\'corrigir\'] : sit === \'embaixador\' || sit === \'sem_closer\' ? [\'dividir\'] : sit === \'de_outro_closer\' ? [\'dividir\', \'total\'] : [])\n\n// ── conferência com o que o closer digitou ───────────────────────────────────────────────────────────────────────\nexport interface PedidoInfo { lead_name: string; product: string; vertical: string }\nexport interface Conf { campo: \'lead\' | \'produto\' | \'vertical\'; rotulo: string; pedido: string; banco: string; status: \'confere\' | \'diverge\' | \'sem_dado\' }\nconst contem = (a: string, b: string) => !!a && !!b && (a === b || a.includes(b) || b.includes(a))\nexport function compararPedido(v: VendaBanco, p: PedidoInfo, rotuloVertical: (x?: string | null) => string): { resumo: \'confere\' | \'parcial\' | \'diverge\'; campos: Conf[] } {\n  const lead = normalizar(v.lead_name), pl = normalizar(p.lead_name), prod = normalizar(v.product), pp = normalizar(p.product)\n  const campos: Conf[] = [\n    { campo: \'lead\', rotulo: \'Nome do lead\', pedido: p.lead_name, banco: v.lead_name ?? \'—\', status: !lead ? \'sem_dado\' : contem(lead, pl) ? \'confere\' : (() => { const a = new Set(lead.split(\' \')), b = pl.split(\' \').filter(x => x.length > 2); return b.length && b.filter(x => a.has(x)).length / b.length >= 0.6 ? \'confere\' : \'diverge\' })() },\n    { campo: \'produto\', rotulo: \'Produto\', pedido: p.product, banco: v.product ?? \'—\', status: !prod ? \'sem_dado\' : contem(prod, pp) ? \'confere\' : \'diverge\' },\n    { campo: \'vertical\', rotulo: \'Vertical\', pedido: rotuloVertical(p.vertical), banco: rotuloVertical(v.vertical), status: !v.vertical ? \'sem_dado\' : v.vertical === p.vertical ? \'confere\' : \'diverge\' },\n  ]\n  const div = campos.filter(c => c.status === \'diverge\').length, ok = campos.filter(c => c.status === \'confere\').length\n  return { resumo: div === 0 ? \'confere\' : ok === 0 ? \'diverge\' : \'parcial\', campos }\n}\n\n// ── tradução da linha do banco ───────────────────────────────────────────────────────────────────────────────────\nexport interface Nomes { principal?: string | null; co?: string | null; regra?: RegraAssinatura | null; regraNome?: string | null }\nexport function traduzir(v: VendaBanco, s: Solicitante, n: Nomes = {}): Linha[] {\n  const L: Linha[] = [], eu = souEu(v, s), org = origemDe(v)\n  const quem = (x?: string | null) => x || \'um closer\'\n  if (org === \'self_checkout\') L.push({ chave: \'origem\', titulo: \'Origem\', tom: \'atencao\', texto: \'Self-Checkout — o lead pagou direto, sem passar por um closer. Hoje esta venda NÃO conta para nenhum closer.\' })\n  else if (org === \'embaixador\') L.push({ chave: \'origem\', titulo: \'Origem\', tom: \'info\', texto: `Venda de Embaixador — fechada pelo cupom ${v.coupon_code ? `"${v.coupon_code}" ` : \'\'}${v.ambassador_name ? `do embaixador ${v.ambassador_name}` : \'de um embaixador\'}. Conta no canal Embaixadores.` })\n  else if (org === \'closer\') L.push({ chave: \'origem\', titulo: \'Origem\', tom: \'info\', texto: \'Venda de Closer — fechada por um closer.\' })\n  else L.push({ chave: \'origem\', titulo: \'Origem\', tom: \'atencao\', texto: \'Origem não identificada (sem tipo de vendedor registrado).\' })\n  const temPrincipal = !!(v.closer_id || hub(v.closer_hubspot_id))\n  if (temPrincipal) {\n    const nome = quem(n.principal ?? v.closer_name)\n    L.push(eu.principal\n      ? { chave: \'closer\', titulo: \'Closer da venda\', tom: \'ok\', texto: `${nome} — é o PRÓPRIO closer que pediu a troca. Já está como Closer.` }\n      : { chave: \'closer\', titulo: \'Closer da venda\', tom: \'atencao\', texto: `${nome} — é OUTRO closer (quem pediu foi ${s.nome}). Alguém já negociou ou registrou esta venda antes.` })\n  } else if (org !== \'self_checkout\') L.push({ chave: \'closer\', titulo: \'Closer da venda\', tom: \'atencao\', texto: \'Nenhum closer está atribuído a esta venda.\' })\n  if (v.co_closer_id || hub(v.co_closer_hubspot_id)) {\n    const quando = v.transferred_at ? ` Transferida em ${fmtDataHora(v.transferred_at)}.` : \'\', motivo = v.transfer_reason ? ` Motivo: ${v.transfer_reason}.` : \'\'\n    L.push({ chave: \'co\', titulo: \'Co-closer\', tom: eu.co ? \'ok\' : \'info\', texto: `${quem(n.co)} também recebe o crédito desta venda (co-closer)${eu.co ? \' — é o closer que pediu a troca\' : \'\'}.${quando}${motivo}` })\n  }\n  if (v.sale_type === \'recorrente\' || v.is_recurring) {\n    const parc = `Parcela ${v.installment_number ?? \'?\'}${v.total_installments ? ` de ${v.total_installments}` : \'\'} de uma assinatura recorrente.`\n    const reg = !v.subscription_id ? \' (sem identificador de assinatura: não dá para criar regra para as próximas).\' : n.regra ? ` Já existe uma regra: as próximas parcelas vão para ${quem(n.regraNome)} (${n.regra.mode === \'correct\' ? \'como correção/closer da venda\' : \'como co-closer\'}).` : \' Ainda NÃO existe regra para as próximas parcelas desta assinatura.\'\n    L.push({ chave: \'recorrencia\', titulo: \'Recorrência\', tom: \'info\', texto: parc + reg })\n  } else L.push({ chave: \'recorrencia\', titulo: \'Tipo\', tom: \'info\', texto: \'Venda nova (primeira cobrança).\' })\n  return L\n}\nexport function sugestaoDe(sit: Situacao, nome: string, n: Nomes = {}): string {\n  switch (sit) {\n    case \'ja_do_solicitante\': return `Nada a transferir: esta venda já está com ${nome}.`\n    case \'self_checkout\': return `“Transferir Venda” transforma esta venda em venda de ${nome} (corrige o Self-Checkout).`\n    case \'embaixador\': return `“Transferir Venda” adiciona ${nome} como co-closer. A venda do embaixador continua intacta (o total da empresa não duplica).`\n    case \'sem_closer\': return `“Transferir Venda” adiciona ${nome} como co-closer desta venda.`\n    case \'de_outro_closer\': return `Esta venda já é de ${n.principal ?? \'outro closer\'}. Ao transferir você escolhe: dividir (${nome} entra como co-closer) ou transferir totalmente (${nome} vira o dono).`\n  }\n}\n\n// ── plano de atualização (mesmos campos da rota pública, mais o necessário no modo "total") ─────────────────────\nexport interface Plano { updates: Record<string, any>; regra: null | { subscription_id: string; mode: \'correct\' | \'co_closer\'; co_closer_id: string; co_closer_hubspot_id: string | null; reason: string }; exige: \'closers\' | \'profiles\' }\nexport function planoAtualizacao(modo: Modo, v: VendaBanco, s: Solicitante, motivo: string, agora: string): Plano {\n  const base: Record<string, any> = { transferred_at: agora, transfer_reason: motivo }\n  let updates: Record<string, any>\n  if (modo === \'dividir\') updates = { ...base, co_closer_id: s.profileId, co_closer_hubspot_id: s.hubspotId }\n  else {\n    updates = { ...base, closer_id: s.closerId, closer_hubspot_id: s.hubspotId, closer_name: s.nome }\n    if (modo === \'corrigir\') { updates.is_self_checkout = false; updates.seller_type = \'closer\' }\n    else if (origemDe(v) !== \'embaixador\') updates.seller_type = \'closer\'\n    if (modo === \'total\' && souEu({ ...v, closer_id: null, closer_hubspot_id: null }, s).co) { updates.co_closer_id = null; updates.co_closer_hubspot_id = null }    // quem era co-closer vira o dono: some a duplicidade\n  }\n  const regra = v.subscription_id && s.profileId ? { subscription_id: v.subscription_id, mode: (modo === \'dividir\' ? \'co_closer\' : \'correct\') as \'correct\' | \'co_closer\', co_closer_id: s.profileId, co_closer_hubspot_id: s.hubspotId, reason: motivo } : null\n  return { updates, regra, exige: modo === \'dividir\' ? \'profiles\' : \'closers\' }\n}\n',
  'lib/vendas/hp-handlers.ts': '// ══ Vendas — handlers de "Consultar HP" e "Transferir Venda" (SÓ superadmin) ═════════════════════════════════════\n//  GET  /api/admin/trocas/:id/consultar-hp  → procura o HP (transaction_id) em telao_events e traduz a linha (NÃO altera nada)\n//  POST /api/admin/trocas/:id/transferir    → transfere a venda para o closer que pediu a troca (mesma lógica da rota pública) e RELÊ o banco para confirmar\nimport type { Ctx, R } from \'./handlers\'\nimport { verticalLabel } from \'./format\'\nimport { compararPedido, escapeLike, modoPadrao, modosPermitidos, planoAtualizacao, situacaoDe, souEu, sugestaoDe, traduzir, type Modo, type Nomes, type Solicitante, type VendaBanco } from \'./hp\'\n\nconst ok = (json: any, status = 200): R => ({ status, json })\nconst err = (status: number, error: string, extra: Record<string, any> = {}): R => ({ status, json: { error, ...extra } })\nconst isSuper = (c: Ctx) => c.role === \'superadmin\'\nconst isUuid = (s: unknown): s is string => typeof s === \'string\' && /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(s)\nconst COLS = \'id, transaction_id, lead_name, email, vertical, product, value, coupon_code, occurred_at, seller_type, is_self_checkout, sold_by_ambassador, ambassador_name, closer_id, closer_name, closer_hubspot_id, co_closer_id, co_closer_hubspot_id, transferred_at, transfer_reason, sale_type, is_recurring, installment_number, total_installments, subscription_id\'\nconst normNome = (s?: string | null) => (s ?? \'\').toLowerCase().normalize(\'NFD\').replace(/[\\u0300-\\u036f]/g, \'\').trim()     // a MESMA normalização do módulo (closers.normalized_name)\nconst AUDIT_FIELDS = [\'closer_id\', \'closer_name\', \'closer_hubspot_id\', \'co_closer_id\', \'co_closer_hubspot_id\', \'is_self_checkout\', \'seller_type\', \'transferred_at\', \'transfer_reason\']\n\nasync function carregarTroca(ctx: Ctx, id: string): Promise<{ ok: false; r: R } | { ok: true; troca: any }> {\n  if (!isUuid(id)) return { ok: false, r: err(400, \'Pedido inválido.\') }\n  const { data, error } = await ctx.admin.from(\'sale_swap_requests\').select(\'*\').eq(\'id\', id).maybeSingle()\n  if (error) return { ok: false, r: err(500, \'Erro ao acessar os dados. Tente novamente em instantes.\') }\n  if (!data) return { ok: false, r: err(404, \'Pedido de troca não encontrado.\') }\n  return { ok: true, troca: data as any }\n}\n/** O closer que pediu, com os dois ids (closers para closer_id; profiles para co_closer_id). */\nasync function solicitante(ctx: Ctx, troca: any): Promise<Solicitante> {\n  const { data: prof } = await ctx.admin.from(\'profiles\').select(\'id, name, hubspot_id\').eq(\'id\', troca.requester_id).maybeSingle()\n  const cols = \'id, name, hubspot_id\'; let closer: any = null\n  if (troca.closer_id) closer = (await ctx.admin.from(\'closers\').select(cols).eq(\'id\', troca.closer_id).maybeSingle()).data\n  const h = String(prof?.hubspot_id ?? \'\').trim()\n  if (!closer && h) closer = (await ctx.admin.from(\'closers\').select(cols).eq(\'hubspot_id\', h).maybeSingle()).data\n  if (!closer) { const n = normNome(prof?.name ?? troca.requester_name); if (n) closer = (await ctx.admin.from(\'closers\').select(cols).eq(\'normalized_name\', n).maybeSingle()).data }\n  const hubspotId = (h || String(closer?.hubspot_id ?? \'\').trim()) || null\n  return { profileId: prof?.id ?? troca.requester_id ?? null, closerId: closer?.id ?? null, hubspotId, nome: prof?.name ?? closer?.name ?? troca.requester_name ?? \'o closer\' }\n}\nasync function buscarVendas(ctx: Ctx, hp: string): Promise<{ vendas: VendaBanco[]; falhou: boolean }> {\n  const { data, error } = await ctx.admin.from(\'telao_events\').select(COLS).eq(\'event_type\', \'sale\').ilike(\'transaction_id\', escapeLike(hp.trim())).order(\'occurred_at\', { ascending: false }).limit(10)\n  return { vendas: (data ?? []) as VendaBanco[], falhou: !!error }\n}\nasync function nomesDe(ctx: Ctx, v: VendaBanco): Promise<Nomes> {\n  const n: Nomes = {}\n  if (v.closer_id) n.principal = (await ctx.admin.from(\'closers\').select(\'name\').eq(\'id\', v.closer_id).maybeSingle()).data?.name ?? null\n  if (v.co_closer_id) n.co = (await ctx.admin.from(\'profiles\').select(\'name\').eq(\'id\', v.co_closer_id).maybeSingle()).data?.name ?? null\n  if (v.subscription_id) {\n    const { data: reg } = await ctx.admin.from(\'subscription_transfers\').select(\'mode, co_closer_id, co_closer_hubspot_id, reason\').eq(\'subscription_id\', v.subscription_id).maybeSingle()\n    if (reg) { n.regra = reg; if (reg.co_closer_id) n.regraNome = (await ctx.admin.from(\'profiles\').select(\'name\').eq(\'id\', reg.co_closer_id).maybeSingle()).data?.name ?? null }\n  }\n  return n\n}\nconst viewVenda = (v: VendaBanco) => ({ id: v.id, hp: v.transaction_id, nome: v.lead_name, email: v.email, vertical: v.vertical, vertical_label: verticalLabel(v.vertical), produto: v.product, valor: v.value == null ? null : Number(v.value), cupom: v.coupon_code, data: v.occurred_at, tipo: v.sale_type })\nasync function outrasParcelas(ctx: Ctx, v: VendaBanco, sol: Solicitante) {\n  if (!v.subscription_id) return { total: 0, pendentes: [] as VendaBanco[] }\n  const { data } = await ctx.admin.from(\'telao_events\').select(COLS).eq(\'event_type\', \'sale\').eq(\'subscription_id\', v.subscription_id).neq(\'id\', v.id).limit(500)\n  const todas = (data ?? []) as VendaBanco[]\n  return { total: todas.length, pendentes: todas.filter(p => { const e = souEu(p, sol); return !e.principal && !e.co }) }\n}\n\nexport async function hConsultarHP(ctx: Ctx, id: string): Promise<R> {\n  if (!isSuper(ctx)) return err(403, \'Só o superadmin pode consultar o HP.\')\n  const t = await carregarTroca(ctx, id); if (!t.ok) return t.r\n  const troca = t.troca, sol = await solicitante(ctx, troca)\n  const { vendas, falhou } = await buscarVendas(ctx, troca.transaction_id)\n  if (falhou) return err(500, \'Não consegui consultar o banco agora. Tente novamente.\')\n  const pedido = { hp: troca.transaction_id, lead_name: troca.lead_name, product: troca.product, vertical: troca.vertical, vertical_label: verticalLabel(troca.vertical), closer: sol.nome }\n  if (vendas.length === 0) {\n    const parecidas = await sugestoes(ctx, troca)\n    return ok({ encontrada: false, quantidade: 0, pedido, parecidas, mensagem: \'Nenhuma venda com este HP no banco. O closer pode ter digitado o ID errado.\' })\n  }\n  const v = vendas[0], nomes = await nomesDe(ctx, v), sit = situacaoDe(v, sol), par = await outrasParcelas(ctx, v, sol)\n  return ok({\n    encontrada: true, quantidade: vendas.length, duplicada: vendas.length > 1, pedido, venda: viewVenda(v),\n    conferencia: compararPedido(v, troca, verticalLabel),\n    traducao: { situacao: sit, linhas: traduzir(v, sol, nomes), sugestao: sugestaoDe(sit, sol.nome, nomes), pode_transferir: vendas.length === 1 && sit !== \'ja_do_solicitante\', modo_padrao: modoPadrao(sit), modos: modosPermitidos(sit) },\n    parcelas: { outras: par.total, pendentes: par.pendentes.length },\n  })\n}\n/** Quando o HP não existe: vendas com nome parecido e HPs que começam igual (ajuda a achar o erro de digitação). */\nasync function sugestoes(ctx: Ctx, troca: any) {\n  const out: any[] = [], ids = new Set<string>()\n  const add = (rows: any[] | null, motivo: string) => { for (const r of rows ?? []) if (r.transaction_id && !ids.has(r.id)) { ids.add(r.id); out.push({ hp: r.transaction_id, nome: r.lead_name, produto: r.product, valor: r.value == null ? null : Number(r.value), data: r.occurred_at, motivo }) } }\n  const hp = String(troca.transaction_id ?? \'\').trim()\n  if (hp.length >= 5) add((await ctx.admin.from(\'telao_events\').select(\'id, transaction_id, lead_name, product, value, occurred_at\').eq(\'event_type\', \'sale\').ilike(\'transaction_id\', escapeLike(hp.slice(0, -1)) + \'%\').order(\'occurred_at\', { ascending: false }).limit(5)).data, \'ID parecido\')\n  const nome = String(troca.lead_name ?? \'\').trim()\n  if (nome.length >= 5) add((await ctx.admin.from(\'telao_events\').select(\'id, transaction_id, lead_name, product, value, occurred_at\').eq(\'event_type\', \'sale\').ilike(\'lead_name\', \'%\' + escapeLike(nome) + \'%\').order(\'occurred_at\', { ascending: false }).limit(5)).data, \'Mesmo nome de lead\')\n  return out.slice(0, 6)\n}\n\nexport async function hTransferirVenda(ctx: Ctx, id: string, body: any): Promise<R> {\n  if (!isSuper(ctx)) return err(403, \'Só o superadmin pode transferir vendas.\')\n  const t = await carregarTroca(ctx, id); if (!t.ok) return t.r\n  const troca = t.troca, sol = await solicitante(ctx, troca)\n  const pedidoModo = [\'corrigir\', \'dividir\', \'total\'].includes(body?.modo) ? (body.modo as Modo) : null\n  if (body?.modo !== undefined && body?.modo !== null && !pedidoModo) return err(400, \'Modo de transferência inválido.\')\n  const incluir = body?.incluir_parcelas === true\n  const base = { pedido: { hp: troca.transaction_id, closer: sol.nome } }\n  const { vendas, falhou } = await buscarVendas(ctx, troca.transaction_id)\n  if (falhou) return err(500, \'Não consegui consultar o banco agora. Tente novamente.\')\n  if (vendas.length === 0) return ok({ ...base, resultado: \'nao_encontrada\', titulo: \'HP não encontrado\', mensagem: \'Não existe venda com este HP no banco. Nada foi alterado. Confira com o closer se o ID está certo (use “Consultar HP”).\', checks: [{ ok: false, texto: `Nenhuma venda com o HP ${troca.transaction_id}` }] })\n  if (vendas.length > 1) return ok({ ...base, resultado: \'bloqueada\', titulo: \'HP duplicado no banco\', mensagem: `Existem ${vendas.length} vendas com este HP. Por segurança nada foi alterado: corrija a duplicidade antes de transferir.`, checks: [{ ok: false, texto: `${vendas.length} linhas com o mesmo HP` }] })\n  const v = vendas[0], sit = situacaoDe(v, sol), eu = souEu(v, sol), par = await outrasParcelas(ctx, v, sol)\n  const nomesAntes = await nomesDe(ctx, v), antes = traduzir(v, sol, nomesAntes)\n  const pendentes = par.pendentes.length\n  if (sit === \'ja_do_solicitante\' && !(incluir && pendentes > 0)) {\n    return ok({ ...base, resultado: \'nada_a_fazer\', titulo: \'Nada a fazer\', mensagem: `Esta venda já está com ${sol.nome}${eu.principal ? \' como Closer\' : \' como co-closer\'}. Nada foi alterado.`, venda: viewVenda(v), depois: antes, parcelas: { outras: par.total, pendentes }, checks: [{ ok: true, texto: `Venda localizada (${v.transaction_id})` }, { ok: true, texto: `Já atribuída a ${sol.nome}` }] })\n  }\n  let modo: Modo | null = sit === \'ja_do_solicitante\' ? (eu.principal ? \'corrigir\' : \'dividir\') : (pedidoModo ?? modoPadrao(sit))\n  if (!modo) return ok({ ...base, resultado: \'precisa_escolher\', titulo: \'Esta venda já é de outro closer\', mensagem: sugestaoDe(sit, sol.nome, nomesAntes), venda: viewVenda(v), antes, opcoes: modosPermitidos(sit), outro: nomesAntes.principal ?? v.closer_name ?? \'outro closer\', checks: [] })\n  if (sit !== \'ja_do_solicitante\' && !modosPermitidos(sit).includes(modo)) return err(400, \'Esse modo não vale para esta venda.\')\n  const motivo = `Troca de venda concedida (pedido de ${sol.nome}) por ${ctx.name ?? \'superadmin\'}`.slice(0, 200)\n  const agora = new Date().toISOString(), plano = planoAtualizacao(modo, v, sol, motivo, agora)\n  if (plano.exige === \'closers\' && !sol.closerId) return ok({ ...base, resultado: \'bloqueada\', titulo: \'Closer sem cadastro em “closers”\', mensagem: `${sol.nome} não está cadastrado na tabela “closers” — necessário para ser o closer principal da venda. Nada foi alterado.`, checks: [{ ok: false, texto: \'Cadastro do closer na tabela closers\' }] })\n  if (plano.exige === \'profiles\' && !sol.profileId) return ok({ ...base, resultado: \'bloqueada\', titulo: \'Closer sem perfil\', mensagem: `${sol.nome} não tem perfil cadastrado — necessário para ser co-closer. Nada foi alterado.`, checks: [{ ok: false, texto: \'Perfil do closer\' }] })\n\n  const checks: { ok: boolean; texto: string; aviso?: boolean }[] = [{ ok: true, texto: `Venda localizada no banco (${v.transaction_id})` }]\n  const antesCampos = Object.fromEntries(AUDIT_FIELDS.map(k => [k, (v as any)[k] ?? null]))\n  if (sit !== \'ja_do_solicitante\') {\n    const { error } = await ctx.admin.from(\'telao_events\').update(plano.updates).eq(\'id\', v.id)\n    if (error) return ok({ ...base, resultado: \'erro\', titulo: \'Não foi possível gravar\', mensagem: \'O banco recusou a alteração. Nada foi transferido.\', detalhe: String(error.message ?? \'\').slice(0, 200), checks: [...checks, { ok: false, texto: \'Gravar a transferência\' }] })\n  }\n  // RELÊ o banco: a confirmação vem da linha de verdade, não do "update deu certo"\n  const { data: rel } = await ctx.admin.from(\'telao_events\').select(COLS).eq(\'id\', v.id).maybeSingle()\n  const depoisV = rel as VendaBanco | null\n  const eu2 = depoisV ? souEu(depoisV, sol) : { principal: false, co: false }\n  const esperado = modo === \'dividir\' ? eu2.co : eu2.principal\n  if (sit !== \'ja_do_solicitante\') checks.push({ ok: !!esperado, texto: modo === \'dividir\' ? `${sol.nome} agora é co-closer desta venda` : modo === \'corrigir\' ? `A venda deixou de ser Self-Checkout e agora é de ${sol.nome}` : `${sol.nome} agora é o closer da venda (substituiu ${nomesAntes.principal ?? v.closer_name ?? \'o anterior\'})` })\n  if (modo === \'corrigir\' && sit !== \'ja_do_solicitante\') checks.push({ ok: depoisV?.is_self_checkout === false, texto: \'Marca de Self-Checkout removida\' })\n  let regraGravada = false\n  if (v.subscription_id) {\n    if (!plano.regra) checks.push({ ok: false, aviso: true, texto: \'Regra das próximas parcelas NÃO criada (closer sem perfil)\' })\n    else {\n      const { error } = await ctx.admin.from(\'subscription_transfers\').upsert(plano.regra, { onConflict: \'subscription_id\' })\n      const { data: reg } = await ctx.admin.from(\'subscription_transfers\').select(\'mode, co_closer_id\').eq(\'subscription_id\', v.subscription_id).maybeSingle()\n      regraGravada = !error && reg?.co_closer_id === sol.profileId\n      checks.push({ ok: regraGravada, aviso: !regraGravada, texto: regraGravada ? \'Regra gravada: as próximas parcelas desta assinatura já nascem com este closer\' : \'Não consegui gravar a regra das próximas parcelas\' })\n    }\n  }\n  let parcelasAplicadas = 0\n  if (incluir && pendentes > 0) {\n    const ids = par.pendentes.map(p => p.id)\n    const { error } = await ctx.admin.from(\'telao_events\').update(plano.updates).in(\'id\', ids)\n    const { data: conf } = await ctx.admin.from(\'telao_events\').select(COLS).in(\'id\', ids)\n    parcelasAplicadas = ((conf ?? []) as VendaBanco[]).filter(p => { const e = souEu(p, sol); return modo === \'dividir\' ? e.co : e.principal }).length\n    checks.push({ ok: !error && parcelasAplicadas === ids.length, aviso: parcelasAplicadas !== ids.length, texto: `Parcelas anteriores atualizadas: ${parcelasAplicadas} de ${ids.length}` })\n  }\n  // auditoria (best effort: se a tabela ainda não existe, a transferência vale mesmo assim e o aviso diz isso)\n  const depoisCampos = depoisV ? Object.fromEntries(AUDIT_FIELDS.map(k => [k, (depoisV as any)[k] ?? null])) : plano.updates\n  const aud = await ctx.admin.from(\'sale_transfer_log\').insert({ troca_id: troca.id, sale_id: v.id, transaction_id: v.transaction_id, modo, requester_id: troca.requester_id, requester_name: sol.nome, performed_by: ctx.userId, performed_by_name: ctx.name, antes: antesCampos, depois: depoisCampos, regra_assinatura: plano.regra, parcelas_afetadas: parcelasAplicadas })\n  checks.push({ ok: !aud.error, aviso: !!aud.error, texto: aud.error ? \'Registro de auditoria não gravado (rode a migração migration-transferencias.sql)\' : \'Registro de auditoria gravado (quem, quando, antes e depois)\' })\n  const par2 = await outrasParcelas(ctx, depoisV ?? v, sol), nomesDepois = depoisV ? await nomesDe(ctx, depoisV) : {}\n  const tudoOk = checks.filter(c => !c.aviso).every(c => c.ok)\n  return ok({ ...base, resultado: tudoOk ? \'transferida\' : \'parcial\', modo, titulo: tudoOk ? \'Venda transferida\' : \'Transferida, com ressalvas\', mensagem: tudoOk ? `${sol.nome} agora ${modo === \'dividir\' ? \'divide o crédito desta venda como co-closer\' : \'é o closer desta venda\'}. Confirmado no banco.` : \'A alteração foi gravada, mas alguma conferência falhou — veja os itens abaixo.\', checks, venda: viewVenda(depoisV ?? v), antes, depois: depoisV ? traduzir(depoisV, sol, nomesDepois) : [], parcelas: { outras: par2.total, pendentes: par2.pendentes.length, aplicadas: parcelasAplicadas }, assinatura: v.subscription_id ? { regra_gravada: regraGravada } : null })\n}\n',
  'components/vendas/HpModais.tsx': '\'use client\'\nimport { useCallback, useEffect, useRef, useState, type ReactNode } from \'react\'\nimport { createPortal } from \'react-dom\'\nimport { motion } from \'framer-motion\'\nimport { AlertTriangle, ArrowRightLeft, CheckCircle2, Copy, Hash, Info, Loader2, Search, ShieldCheck, Split, UserCheck, X, XCircle, Mail, Package, Tag, User, Wallet } from \'lucide-react\'\nimport type { TrocaRow } from \'@/lib/vendas/types\'\nimport { fmtBRL, fmtDataHora } from \'@/lib/vendas/format\'\nimport { Btn, VerticalChip } from \'./ui\'\n\n// ══ Popups do superadmin na troca de venda: "Consultar HP" (só lê) e "Transferir Venda" (grava e confirma) ════════════\nconst COR = { ok: \'#16a34a\', atencao: \'#d97706\', erro: \'#dc2626\', info: \'#6366f1\' }\nconst TOM_ICONE = { ok: CheckCircle2, atencao: AlertTriangle, erro: XCircle, info: Info } as const\nconst lbl: React.CSSProperties = { display: \'flex\', alignItems: \'center\', gap: 6, fontSize: 11, fontWeight: 800, letterSpacing: \'0.07em\', textTransform: \'uppercase\', color: \'var(--muted-foreground)\' }\n\nfunction Shell({ cor, icone, titulo, subtitulo, onClose, children, rodape, dataV }: { cor: string; icone: ReactNode; titulo: string; subtitulo?: ReactNode; onClose: () => void; children: ReactNode; rodape?: ReactNode; dataV: string }) {\n  useEffect(() => {\n    const esc = (e: KeyboardEvent) => { if (e.key === \'Escape\') onClose() }\n    window.addEventListener(\'keydown\', esc); const prev = document.body.style.overflow; document.body.style.overflow = \'hidden\'\n    return () => { window.removeEventListener(\'keydown\', esc); document.body.style.overflow = prev }\n  }, [onClose])\n  if (typeof document === \'undefined\') return null\n  return createPortal(\n    <motion.div data-v={dataV} initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ duration: 0.15 }} onMouseDown={e => { if (e.target === e.currentTarget) onClose() }}\n      style={{ position: \'fixed\', inset: 0, zIndex: 1000, background: \'rgba(10,14,30,.55)\', backdropFilter: \'blur(7px)\', display: \'flex\', alignItems: \'center\', justifyContent: \'center\', padding: 16 }}>\n      <motion.div role="dialog" aria-modal="true" aria-label={titulo} initial={{ opacity: 0, y: 18, scale: 0.96 }} animate={{ opacity: 1, y: 0, scale: 1 }} transition={{ type: \'spring\', stiffness: 380, damping: 30 }}\n        style={{ width: \'min(680px, 100%)\', maxHeight: \'min(90vh, 860px)\', display: \'flex\', flexDirection: \'column\', background: \'var(--card)\', border: \'1px solid var(--border)\', borderRadius: 26, boxShadow: \'0 40px 90px -30px rgba(0,0,0,.55)\', overflow: \'hidden\' }}>\n        <div style={{ position: \'relative\', padding: \'22px 26px\', display: \'flex\', alignItems: \'center\', gap: 16, background: `linear-gradient(135deg, color-mix(in srgb, ${cor} 16%, var(--card)), color-mix(in srgb, ${cor} 5%, var(--card)))`, borderBottom: `1px solid color-mix(in srgb, ${cor} 25%, var(--border))` }}>\n          <span aria-hidden style={{ position: \'absolute\', inset: \'0 auto 0 0\', width: 6, background: cor }} />\n          <span style={{ width: 48, height: 48, borderRadius: 15, display: \'flex\', alignItems: \'center\', justifyContent: \'center\', color: \'#fff\', background: `linear-gradient(135deg, ${cor}, color-mix(in srgb, ${cor} 65%, #000))`, boxShadow: `0 10px 24px -10px ${cor}`, flexShrink: 0 }}>{icone}</span>\n          <div style={{ flex: 1, minWidth: 0 }}>\n            <h3 data-v="hp-titulo" style={{ margin: 0, fontSize: 19, fontWeight: 900, letterSpacing: \'-0.02em\', color: \'var(--foreground)\' }}>{titulo}</h3>\n            {subtitulo && <div style={{ marginTop: 3, fontSize: 13, color: \'var(--muted-foreground)\' }}>{subtitulo}</div>}\n          </div>\n          <button type="button" data-v="hp-fechar-x" aria-label="Fechar" onClick={onClose} className="vd-btn" style={{ width: 36, height: 36, borderRadius: 11, border: \'1px solid var(--border)\', background: \'var(--card)\', color: \'var(--muted-foreground)\', cursor: \'pointer\', display: \'flex\', alignItems: \'center\', justifyContent: \'center\' }}><X size={17} /></button>\n        </div>\n        <div style={{ padding: \'22px 26px\', overflowY: \'auto\', display: \'flex\', flexDirection: \'column\', gap: 20 }}>{children}</div>\n        <div style={{ padding: \'16px 26px\', borderTop: \'1px solid var(--border)\', display: \'flex\', alignItems: \'center\', justifyContent: \'flex-end\', gap: 12, flexWrap: \'wrap\', background: \'var(--secondary)\' }}>{rodape}<Btn data-v="hp-fechar" onClick={onClose}>Fechar</Btn></div>\n      </motion.div>\n    </motion.div>, document.body)\n}\nconst Secao = ({ titulo, children, dataV }: { titulo: string; children: ReactNode; dataV?: string }) => <section data-v={dataV}><div style={{ ...lbl, marginBottom: 10 }}>{titulo}</div>{children}</section>\nfunction Tile({ icon, rotulo, children, dataV, full }: { icon: ReactNode; rotulo: string; children: ReactNode; dataV: string; full?: boolean }) {\n  return <div style={{ padding: \'12px 14px\', borderRadius: 14, background: \'var(--secondary)\', minWidth: 0, gridColumn: full ? \'1 / -1\' : undefined }}><div style={lbl}>{icon}{rotulo}</div><div data-v={dataV} style={{ marginTop: 6, fontSize: 14.5, fontWeight: 700, color: \'var(--foreground)\', overflowWrap: \'anywhere\' }}>{children}</div></div>\n}\nfunction Linha({ tom, titulo, texto }: { tom: keyof typeof COR; titulo?: string; texto: string }) {\n  const Ic = TOM_ICONE[tom], c = COR[tom]\n  return (\n    <div data-v="hp-linha" data-tom={tom} style={{ display: \'flex\', gap: 12, padding: \'12px 14px\', borderRadius: 14, background: `color-mix(in srgb, ${c} 7%, var(--card))`, border: `1px solid color-mix(in srgb, ${c} 22%, transparent)` }}>\n      <Ic size={18} color={c} style={{ flexShrink: 0, marginTop: 1 }} />\n      <div style={{ fontSize: 13.5, lineHeight: 1.55, color: \'var(--foreground)\' }}>{titulo && <strong style={{ display: \'block\', fontSize: 11.5, letterSpacing: \'0.05em\', textTransform: \'uppercase\', color: c, marginBottom: 2 }}>{titulo}</strong>}{texto}</div>\n    </div>\n  )\n}\nconst copiar = (t: string) => { try { void navigator.clipboard.writeText(t) } catch { /* */ } }\n\n// ── Consultar HP ─────────────────────────────────────────────────────────────────────────────────────────────────\nexport function ConsultarHpModal({ troca, onClose }: { troca: TrocaRow; onClose: () => void }) {\n  const [d, setD] = useState<any>(null); const [erro, setErro] = useState<string | null>(null)\n  useEffect(() => {\n    let off = false\n    ;(async () => {\n      try {\n        const r = await fetch(`/api/admin/trocas/${troca.id}/consultar-hp`, { cache: \'no-store\' }); const j = await r.json().catch(() => ({}))\n        if (off) return; if (!r.ok) setErro(j.error ?? \'Não foi possível consultar o HP.\'); else setD(j)\n      } catch { if (!off) setErro(\'Erro de conexão. Tente de novo.\') }\n    })()\n    return () => { off = true }\n  }, [troca.id])\n  const achou = d?.encontrada === true, conf = d?.conferencia?.resumo as string | undefined\n  const estado = erro ? { cor: COR.erro, t: \'Não foi possível consultar\', i: <XCircle size={24} /> }\n    : !d ? { cor: COR.info, t: \'Consultando o banco…\', i: <Loader2 size={24} className="vd-spin" /> }\n    : !achou ? { cor: COR.erro, t: \'HP não encontrado no banco\', i: <XCircle size={24} /> }\n    : d.duplicada ? { cor: COR.atencao, t: \'HP duplicado no banco\', i: <AlertTriangle size={24} /> }\n    : conf === \'confere\' ? { cor: COR.ok, t: \'HP encontrado e confere\', i: <ShieldCheck size={24} /> }\n    : { cor: COR.atencao, t: \'HP encontrado — confira as divergências\', i: <AlertTriangle size={24} /> }\n  const v = d?.venda\n  return (\n    <Shell dataV="hp-modal-consulta" cor={estado.cor} icone={estado.i} titulo={estado.t} onClose={onClose}\n      subtitulo={<span style={{ display: \'inline-flex\', alignItems: \'center\', gap: 6 }}><Hash size={13} /><span data-v="hp-id" style={{ fontFamily: \'ui-monospace, monospace\', fontWeight: 700 }}>{troca.transaction_id}</span> · pedido de {troca.requester_name}</span>}>\n      {!d && !erro && <div data-v="hp-carregando" style={{ display: \'flex\', flexDirection: \'column\', gap: 10 }}>{[1, 2, 3].map(i => <div key={i} style={{ height: 54, borderRadius: 14, background: \'var(--secondary)\', opacity: 0.7 }} />)}</div>}\n      {erro && <div data-v="hp-erro" role="alert"><Linha tom="erro" texto={erro} /></div>}\n      {d && !achou && (<>\n        <div data-v="hp-nao-encontrado"><Linha tom="erro" titulo="Não existe venda com este HP" texto={d.mensagem} /></div>\n        <Secao titulo="Você quis dizer?" dataV="hp-parecidas">\n          {d.parecidas?.length ? <div style={{ display: \'flex\', flexDirection: \'column\', gap: 8 }}>{d.parecidas.map((p: any) => (\n            <div key={p.hp} data-v="hp-parecida" style={{ display: \'flex\', alignItems: \'center\', gap: 12, padding: \'11px 14px\', borderRadius: 14, background: \'var(--secondary)\' }}>\n              <div style={{ flex: 1, minWidth: 0 }}><div style={{ fontFamily: \'ui-monospace, monospace\', fontWeight: 800, fontSize: 14 }}>{p.hp}</div><div style={{ fontSize: 12.5, color: \'var(--muted-foreground)\', overflowWrap: \'anywhere\' }}>{p.nome} · {p.produto} · {fmtBRL(p.valor)} · {fmtDataHora(p.data)}</div></div>\n              <span style={{ fontSize: 11, fontWeight: 800, color: COR.info }}>{p.motivo}</span>\n              <button type="button" className="vd-btn" title="Copiar HP" onClick={() => copiar(p.hp)} style={{ width: 34, height: 34, borderRadius: 10, border: \'1px solid var(--border)\', background: \'var(--card)\', cursor: \'pointer\', display: \'flex\', alignItems: \'center\', justifyContent: \'center\', color: \'var(--foreground)\' }}><Copy size={14} /></button>\n            </div>))}</div>\n            : <p style={{ margin: 0, fontSize: 13.5, color: \'var(--muted-foreground)\' }}>Nenhuma venda parecida encontrada (nem pelo início do ID, nem pelo nome do lead).</p>}\n        </Secao>\n      </>)}\n      {d && achou && (<>\n        {d.duplicada && <div data-v="hp-duplicado"><Linha tom="atencao" titulo="Atenção" texto={`Existem ${d.quantidade} vendas com este HP. Mostrando a mais recente. A transferência fica bloqueada até corrigir a duplicidade.`} /></div>}\n        <Secao titulo="Dados da venda no banco" dataV="hp-dados">\n          <div style={{ display: \'grid\', gridTemplateColumns: \'repeat(auto-fit, minmax(240px, 1fr))\', gap: 10 }}>\n            <Tile icon={<User size={13} />} rotulo="Nome do Lead" dataV="hp-nome">{v.nome ?? \'—\'}</Tile>\n            <Tile icon={<Mail size={13} />} rotulo="E-mail" dataV="hp-email">{v.email ?? \'—\'}</Tile>\n            <Tile icon={<Tag size={13} />} rotulo="Vertical" dataV="hp-vertical">{v.vertical ? <VerticalChip v={v.vertical} /> : \'—\'}</Tile>\n            <Tile icon={<Wallet size={13} />} rotulo="Valor" dataV="hp-valor"><span style={{ fontSize: 17, fontWeight: 900 }}>{fmtBRL(v.valor)}</span></Tile>\n            <Tile icon={<Package size={13} />} rotulo="Produto" dataV="hp-produto" full>{v.produto ?? \'—\'}</Tile>\n            <Tile icon={<Tag size={13} />} rotulo="Cupom" dataV="hp-cupom">{v.cupom ? <span style={{ fontFamily: \'ui-monospace, monospace\', padding: \'2px 9px\', borderRadius: 8, background: \'color-mix(in srgb, #6366f1 12%, transparent)\', color: \'#6366f1\' }}>{v.cupom}</span> : <span style={{ color: \'var(--muted-foreground)\' }}>sem cupom</span>}</Tile>\n            <Tile icon={<Hash size={13} />} rotulo="Data da venda" dataV="hp-data">{fmtDataHora(v.data)}</Tile>\n          </div>\n        </Secao>\n        <Secao titulo="Como esta venda está no banco" dataV="hp-traducao">\n          <div style={{ display: \'flex\', flexDirection: \'column\', gap: 8 }}>{d.traducao.linhas.map((l: any) => <Linha key={l.chave} tom={l.tom} titulo={l.titulo} texto={l.texto} />)}</div>\n          <p data-v="hp-sugestao" style={{ margin: \'12px 2px 0\', fontSize: 13, lineHeight: 1.55, color: \'var(--muted-foreground)\' }}><strong style={{ color: \'var(--foreground)\' }}>O que fazer: </strong>{d.traducao.sugestao}</p>\n          {d.parcelas?.outras > 0 && <p data-v="hp-parcelas" style={{ margin: \'6px 2px 0\', fontSize: 12.5, color: \'var(--muted-foreground)\' }}>Esta assinatura tem mais {d.parcelas.outras} parcela(s) registrada(s); {d.parcelas.pendentes} ainda não {d.parcelas.pendentes === 1 ? \'é\' : \'são\'} de {d.pedido.closer}.</p>}\n        </Secao>\n        <Secao titulo="Confere com o que o closer digitou?" dataV="hp-conferencia">\n          <div style={{ display: \'flex\', flexWrap: \'wrap\', gap: 8 }}>{d.conferencia.campos.filter((c: any) => c.status === \'confere\').map((c: any) => <span key={c.campo} data-v="hp-conf-ok" title={`“${c.banco}”`} className="vd-chip" style={{ padding: \'6px 12px\', borderRadius: 99, fontSize: 12.5, fontWeight: 700, color: COR.ok, background: `color-mix(in srgb, ${COR.ok} 12%, transparent)` }}><CheckCircle2 size={14} />{c.rotulo} confere</span>)}</div>\n          <div style={{ display: \'flex\', flexDirection: \'column\', gap: 8, marginTop: d.conferencia.campos.some((c: any) => c.status !== \'confere\') ? 10 : 0 }}>{d.conferencia.campos.filter((c: any) => c.status !== \'confere\').map((c: any) => (\n            <Linha key={c.campo} tom={c.status === \'diverge\' ? \'atencao\' : \'info\'} titulo={c.rotulo}\n              texto={c.status === \'diverge\' ? `Diverge — o closer informou “${c.pedido}”, mas no banco está “${c.banco}”` : `Sem dado no banco para comparar (o closer informou “${c.pedido}”)`} />))}</div>\n        </Secao>\n      </>)}\n    </Shell>\n  )\n}\n\n// ── Transferir Venda ─────────────────────────────────────────────────────────────────────────────────────────────\ntype Estado = { fase: \'executando\' } | { fase: \'ok\'; r: any } | { fase: \'erro\'; msg: string }\nexport function TransferirVendaModal({ troca, onClose, onTransferida }: { troca: TrocaRow; onClose: () => void; onTransferida?: (r: any) => void }) {\n  const [e, setE] = useState<Estado>({ fase: \'executando\' }); const iniciou = useRef(false)\n  const executar = useCallback(async (corpo: Record<string, any>) => {\n    setE({ fase: \'executando\' })\n    try {\n      const r = await fetch(`/api/admin/trocas/${troca.id}/transferir`, { method: \'POST\', headers: { \'Content-Type\': \'application/json\' }, body: JSON.stringify(corpo) }); const j = await r.json().catch(() => ({}))\n      if (!r.ok) { setE({ fase: \'erro\', msg: j.error ?? \'Não foi possível transferir a venda.\' }); return }\n      setE({ fase: \'ok\', r: j }); if (j.resultado === \'transferida\' || j.resultado === \'parcial\') onTransferida?.(j)\n    } catch { setE({ fase: \'erro\', msg: \'Erro de conexão. Nada foi confirmado: consulte o HP para ver como ficou.\' }) }\n  }, [troca.id, onTransferida])\n  useEffect(() => { if (iniciou.current) return; iniciou.current = true; void executar({}) }, [executar])      // 1 clique = 1 transferência (a guarda evita rodar 2× no modo estrito do React)\n  const r = e.fase === \'ok\' ? e.r : null, res = r?.resultado as string | undefined\n  const cor = e.fase === \'executando\' ? COR.info : e.fase === \'erro\' ? COR.erro : res === \'transferida\' ? COR.ok : res === \'parcial\' || res === \'precisa_escolher\' ? COR.atencao : res === \'nada_a_fazer\' ? COR.info : COR.erro\n  const icone = e.fase === \'executando\' ? <Loader2 size={24} className="vd-spin" /> : res === \'transferida\' ? <CheckCircle2 size={24} /> : res === \'precisa_escolher\' ? <Split size={24} /> : res === \'nada_a_fazer\' ? <UserCheck size={24} /> : res === \'parcial\' ? <AlertTriangle size={24} /> : <XCircle size={24} />\n  const titulo = e.fase === \'executando\' ? \'Transferindo a venda…\' : e.fase === \'erro\' ? \'Não foi possível transferir\' : r.titulo\n  const pend = r?.parcelas?.pendentes ?? 0\n  return (\n    <Shell dataV="hp-modal-transferir" cor={cor} icone={icone} titulo={titulo} onClose={onClose}\n      subtitulo={<span style={{ display: \'inline-flex\', alignItems: \'center\', gap: 6 }}><ArrowRightLeft size={13} />HP <span style={{ fontFamily: \'ui-monospace, monospace\', fontWeight: 700 }}>{troca.transaction_id}</span> → {troca.requester_name}</span>}\n      rodape={res === \'transferida\' || res === \'parcial\' ? <span data-v="hp-proximo-passo" style={{ marginRight: \'auto\', fontSize: 12.5, color: \'var(--muted-foreground)\' }}>Agora escreva a justificativa e confirme a concessão.</span> : undefined}>\n      {e.fase === \'executando\' && <div data-v="hp-executando" style={{ display: \'flex\', alignItems: \'center\', gap: 14, padding: \'8px 2px\', color: \'var(--muted-foreground)\', fontSize: 14 }}><Loader2 size={20} className="vd-spin" />Verificando o HP no banco, gravando a transferência e conferindo o resultado…</div>}\n      {e.fase === \'erro\' && <div data-v="hp-erro" role="alert"><Linha tom="erro" texto={e.msg} /></div>}\n      {r && (<>\n        <div data-v="hp-resultado" data-resultado={res}><Linha tom={res === \'transferida\' ? \'ok\' : res === \'precisa_escolher\' || res === \'parcial\' ? \'atencao\' : res === \'nada_a_fazer\' ? \'info\' : \'erro\'} texto={r.mensagem} /></div>\n        {res === \'precisa_escolher\' && (\n          <Secao titulo="Como transferir?" dataV="hp-escolha">\n            <div style={{ display: \'grid\', gridTemplateColumns: \'repeat(auto-fit, minmax(250px, 1fr))\', gap: 12 }}>\n              <button type="button" data-v="hp-opcao-dividir" className="vd-btn" onClick={() => executar({ modo: \'dividir\' })} style={{ textAlign: \'left\', padding: 16, borderRadius: 16, border: \'1.5px solid var(--border)\', background: \'var(--card)\', cursor: \'pointer\', color: \'var(--foreground)\' }}>\n                <Split size={20} color={COR.info} /><div style={{ marginTop: 8, fontWeight: 800, fontSize: 15 }}>Dividir o crédito</div><div style={{ marginTop: 4, fontSize: 12.5, lineHeight: 1.5, color: \'var(--muted-foreground)\' }}>{troca.requester_name} entra como <strong>co-closer</strong> e {r.outro} continua como closer. Os dois recebem; o total da empresa não duplica.</div>\n              </button>\n              <button type="button" data-v="hp-opcao-total" className="vd-btn" onClick={() => executar({ modo: \'total\' })} style={{ textAlign: \'left\', padding: 16, borderRadius: 16, border: \'1.5px solid var(--border)\', background: \'var(--card)\', cursor: \'pointer\', color: \'var(--foreground)\' }}>\n                <ArrowRightLeft size={20} color={COR.atencao} /><div style={{ marginTop: 8, fontWeight: 800, fontSize: 15 }}>Transferir totalmente</div><div style={{ marginTop: 4, fontSize: 12.5, lineHeight: 1.5, color: \'var(--muted-foreground)\' }}>{troca.requester_name} passa a ser o <strong>dono</strong> da venda e {r.outro} deixa de ter o crédito.</div>\n              </button>\n            </div>\n          </Secao>\n        )}\n        {r.checks?.length > 0 && (\n          <Secao titulo="Conferência no banco" dataV="hp-checks">\n            <div style={{ display: \'flex\', flexDirection: \'column\', gap: 8 }}>{r.checks.map((c: any, i: number) => <Linha key={i} tom={c.ok ? \'ok\' : c.aviso ? \'atencao\' : \'erro\'} texto={c.texto} />)}</div>\n          </Secao>\n        )}\n        {(res === \'transferida\' || res === \'parcial\') && r.depois?.length > 0 && (\n          <Secao titulo="Como ficou" dataV="hp-depois"><div style={{ display: \'flex\', flexDirection: \'column\', gap: 8 }}>{r.depois.map((l: any) => <Linha key={l.chave} tom={l.tom} titulo={l.titulo} texto={l.texto} />)}</div></Secao>\n        )}\n        {(res === \'transferida\' || res === \'parcial\' || res === \'nada_a_fazer\') && pend > 0 && r.parcelas?.aplicadas === 0 && (\n          <div data-v="hp-parcelas-bloco" style={{ padding: 16, borderRadius: 16, background: \'color-mix(in srgb, #6366f1 7%, var(--card))\', border: \'1px dashed color-mix(in srgb, #6366f1 40%, transparent)\' }}>\n            <div style={{ fontSize: 13.5, lineHeight: 1.55 }}>Esta é uma assinatura recorrente: existem <strong>{pend}</strong> parcela(s) já registrada(s) que ainda não {pend === 1 ? \'é\' : \'são\'} de {troca.requester_name}. As próximas já seguem a regra gravada; as anteriores só mudam se você pedir.</div>\n            <div style={{ marginTop: 12 }}><Btn data-v="hp-aplicar-parcelas" variant="soft" icon={<Copy size={15} />} onClick={() => executar({ modo: r.modo, incluir_parcelas: true })}>Aplicar também às {pend} parcela(s) anterior(es)</Btn></div>\n          </div>\n        )}\n      </>)}\n    </Shell>\n  )\n}\n',
  'app/api/admin/trocas/[id]/consultar-hp/route.ts': "import { comCtx } from '@/lib/vendas/route'\nimport { hConsultarHP } from '@/lib/vendas/hp-handlers'\nexport const dynamic = 'force-dynamic'\n// Superadmin: confere se o HP (transaction_id) do pedido existe no banco e mostra a linha traduzida. NÃO altera nada.\nexport async function GET(_req: Request, { params }: { params: Promise<{ id: string }> }) {\n  const { id } = await params\n  return comCtx(ctx => hConsultarHP(ctx, id))\n}\n",
  'app/api/admin/trocas/[id]/transferir/route.ts': "import { comCtx, lerJson } from '@/lib/vendas/route'\nimport { hTransferirVenda } from '@/lib/vendas/hp-handlers'\nexport const dynamic = 'force-dynamic'\n// Superadmin: transfere a venda do HP do pedido para o closer que pediu (corrige self-checkout, divide como co-closer ou transfere totalmente) e confirma lendo o banco.\nexport async function POST(req: Request, { params }: { params: Promise<{ id: string }> }) {\n  const { id } = await params; const body = await lerJson(req)\n  return comCtx(ctx => hTransferirVenda(ctx, id, body))\n}\n",
}
EDITS = {
  'components/vendas/TrocaCard.tsx': [
    ('exact', "import { ConsultarHpModal, TransferirVendaModal } from './HpModais'", "import { Avatar, Banner, Btn, TeamBadge, TextArea, VerticalChip } from './ui'", "import { Avatar, Banner, Btn, TeamBadge, TextArea, VerticalChip } from './ui'\nimport { ArrowRightLeft, Search as SearchIcon } from 'lucide-react'\nimport { ConsultarHpModal, TransferirVendaModal } from './HpModais'", 'imports dos popups do superadmin'),
    ('exact', 'const [hpAberto, setHpAberto]', '  const corModo = modo ? COR_STATUS[modo] : cor', '  const [hpAberto, setHpAberto] = useState(false); const [transfAberto, setTransfAberto] = useState(false); const [transferida, setTransferida] = useState<string | null>(null)\n  const corModo = modo ? COR_STATUS[modo] : cor', 'estados dos popups (Consultar HP / Transferir Venda)'),
    ('exact', 'data-v="troca-consultar-hp"', '        </Info>\n        <Info icon={<User size={13} />} label="Nome do Lead">{t.lead_name}</Info>', '          {admin && <div style={{ marginTop: 10 }}><Btn data-v="troca-consultar-hp" size="sm" variant="soft" icon={<SearchIcon size={14} />} onClick={() => setHpAberto(true)} title="Conferir se este HP existe no banco e como a venda está registrada">Consultar HP</Btn></div>}\n        </Info>\n        <Info icon={<User size={13} />} label="Nome do Lead">{t.lead_name}</Info>', 'botão "Consultar HP" (só superadmin) ao lado do ID da transação'),
    ('exact', 'data-v="troca-transferir-bloco"', '<TextArea data-v="troca-resposta-campo" autoFocus', '{modo === \'concedida\' && (\n                    <div data-v="troca-transferir-bloco" style={{ display: \'flex\', alignItems: \'center\', gap: 12, flexWrap: \'wrap\', padding: \'12px 14px\', borderRadius: 14, background: \'color-mix(in srgb, #6366f1 7%, var(--card))\', border: \'1px dashed color-mix(in srgb, #6366f1 40%, transparent)\' }}>\n                      <Btn data-v="troca-transferir" variant="soft" icon={<ArrowRightLeft size={15} />} onClick={() => setTransfAberto(true)}>Transferir Venda</Btn>\n                      {transferida ? <span data-v="troca-transferida" style={{ display: \'inline-flex\', alignItems: \'center\', gap: 6, fontSize: 12.5, fontWeight: 800, color: \'#16a34a\' }}><CheckCircle2 size={14} />Venda transferida no banco</span> : <span style={{ fontSize: 12.5, color: \'var(--muted-foreground)\' }}>Passa a venda do HP para {t.requester_name} no banco, antes de você responder.</span>}\n                    </div>\n                  )}\n                  <TextArea data-v="troca-resposta-campo" autoFocus', 'botão "Transferir Venda" dentro do Conceder (antes de escrever a resposta)'),
    ('exact', '{admin && hpAberto && <ConsultarHpModal', '    </motion.article>\n  )\n}', '      {admin && hpAberto && <ConsultarHpModal troca={t} onClose={() => setHpAberto(false)} />}\n      {admin && transfAberto && <TransferirVendaModal troca={t} onClose={() => setTransfAberto(false)} onTransferida={r => setTransferida(r.resultado)} />}\n    </motion.article>\n  )\n}', 'renderiza os popups')
  ],
}

BAK = '.bak-hp'

def aplica(texto, edits):
    novo, msgs, ok = texto, [], True
    for tipo, marcador, antes, depois, desc in edits:
        if marcador in novo: msgs.append(f'  · já estava assim: {desc}'); continue
        if tipo == 'regex':
            ms = list(re.finditer(antes, novo)); n = len(ms)
            if n != 1: ok = False; msgs.append(f'  ✗ {desc}: o trecho esperado apareceu {n} vez(es) (precisa ser exatamente 1) — arquivo NÃO alterado'); continue
            m = ms[0]; rep = depois
            for i, gp in enumerate(m.groups(), 1): rep = rep.replace(f'@{i}@', gp)
            novo = novo[:m.start()] + rep + novo[m.end():]; msgs.append(f'  ✓ alterado: {desc}'); continue
        n = novo.count(antes)
        if n != 1: ok = False; msgs.append(f'  ✗ {desc}: o trecho esperado apareceu {n} vez(es) (precisa ser exatamente 1) — arquivo NÃO alterado'); continue
        novo = novo.replace(antes, depois); msgs.append(f'  ✓ alterado: {desc}')
    return novo, msgs, ok

def main(argv):
    args = [a for a in argv if not a.startswith('--')]; raiz = args[0] if args else '.'
    modo = 'desfazer' if '--desfazer' in argv else 'dry' if '--dry-run' in argv else 'aplicar'
    if not os.path.isdir(os.path.join(raiz, 'app')) or not os.path.isdir(os.path.join(raiz, 'lib')):
        print('Rode na RAIZ do projeto (onde ficam as pastas app/ e lib/), ex.: python aplicar-consultar-hp.py .'); return 2
    print({'aplicar': 'APLICANDO', 'dry': 'SIMULAÇÃO (nada será gravado)', 'desfazer': 'DESFAZENDO'}[modo], '— Troca de venda: Consultar HP e Transferir Venda\n')
    P = lambda rel: os.path.join(raiz, *rel.split('/'))
    falhas = 0
    if modo == 'desfazer':
        for rel in EDITS:
            p = P(rel)
            if os.path.isfile(p + BAK): os.replace(p + BAK, p); print(f'✔ {rel}\n  ✓ restaurado da cópia de segurança')
            else: print(f'✔ {rel}\n  · sem cópia de segurança: nada a desfazer')
        for rel, txt in NOVOS.items():
            p = P(rel)
            if os.path.isfile(p):
                if open(p, encoding='utf-8', newline='').read().replace('\r\n', '\n') == txt: os.remove(p); print(f'✔ {rel}\n  ✓ arquivo novo removido')
                else: print(f'✘ {rel}\n  ✗ foi alterado depois de criado: NÃO removi'); falhas += 1
        print('\nTudo certo.' if not falhas else f'\n{falhas} problema(s).'); return 1 if falhas else 0
    plano = []
    for rel, txt in NOVOS.items():
        p = P(rel)
        if os.path.isfile(p):
            if open(p, encoding='utf-8', newline='').read().replace('\r\n', '\n') == txt: print(f'✔ {rel}\n  · já estava assim (arquivo novo já criado)'); continue
            print(f'✘ {rel}\n  ✗ já existe e é DIFERENTE do esperado — NÃO alterado'); falhas += 1; continue
        print(f'✔ {rel}\n  ✓ criado (arquivo novo)'); plano.append(('novo', p, txt, None, None))
    for rel, edits in EDITS.items():
        p = P(rel)
        if not os.path.isfile(p): print(f'✘ {rel}\n  ✗ arquivo não encontrado'); falhas += 1; continue
        bruto = open(p, 'rb').read(); bom = bruto.startswith(b'\xef\xbb\xbf'); crlf = b'\r\n' in bruto
        texto = bruto.decode('utf-8-sig').replace('\r\n', '\n')
        novo, msgs, ok = aplica(texto, edits)
        print(('✔ ' if ok else '✘ ') + rel); print('\n'.join(msgs)); falhas += not ok
        if ok and novo != texto: plano.append(('edit', p, novo, bruto, (bom, crlf)))
    if modo == 'aplicar':
        for tipo, p, conteudo, bruto, fmt in plano:
            if tipo == 'novo': os.makedirs(os.path.dirname(p), exist_ok=True); open(p, 'wb').write(conteudo.encode('utf-8')); continue
            if not os.path.isfile(p + BAK): open(p + BAK, 'wb').write(bruto)
            bom, crlf = fmt; saida = conteudo.replace('\n', '\r\n') if crlf else conteudo; dados = saida.encode('utf-8'); dados = (b'\xef\xbb\xbf' + dados) if bom else dados
            tmp = p + '.faixas.tmp'; open(tmp, 'wb').write(dados); os.replace(tmp, p)
    print('\nTudo certo.' if not falhas else f'\n{falhas} arquivo(s) com problema (os demais foram processados).')
    return 1 if falhas else 0

if __name__ == '__main__': sys.exit(main(sys.argv[1:]))
